import { parseCsvLine, CsvError } from "./src/csv.mjs";
// Independent reference: character state machine straight from README.
function ref(text) {
  if (typeof text !== "string") throw new TypeError("x");
  let end = text.length;
  if (text.endsWith("\r\n")) end -= 2; else if (text.endsWith("\n")) end -= 1;
  const out = []; let f = ""; let state = "start"; // start | unq | inq | afterq
  for (let i = 0; i < end; i++) {
    const c = text[i];
    if (state === "start") {
      if (c === "\"") state = "inq";
      else if (c === ",") { out.push(""); }
      else if (c === "\n" || c === "\r") throw new CsvError("lb");
      else { f = c; state = "unq"; }
    } else if (state === "unq") {
      if (c === ",") { out.push(f); f = ""; state = "start"; }
      else if (c === "\"") throw new CsvError("q");
      else if (c === "\n" || c === "\r") throw new CsvError("lb");
      else f += c;
    } else if (state === "inq") {
      if (c === "\"") { if (i + 1 < end && text[i+1] === "\"") { f += "\""; i++; } else state = "afterq"; }
      else f += c;
    } else { // afterq
      if (c === ",") { out.push(f); f = ""; state = "start"; }
      else throw new CsvError("after");
    }
  }
  if (state === "inq") throw new CsvError("unclosed");
  out.push(f);
  return out;
}
let seed = 12345;
const rand = (n) => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed % n; };
const alphabet = ["\"", "\"", "\"", ",", ",", "\n", "\r", "\r\n", " ", "a", "b", "\t", "\u0000", "🙂", "\ud800", "\udc00", "\u0085", " ", "\\", "__proto__"];
let mismatches = 0;
for (let round = 0; round < 400000 && mismatches < 10; round++) {
  const len = rand(24);
  let s = "";
  for (let k = 0; k < len; k++) s += alphabet[rand(alphabet.length)];
  let a, ea, b, eb;
  try { a = parseCsvLine(s); } catch (e) { ea = e; }
  try { b = ref(s); } catch (e) { eb = e; }
  const ok = (ea && eb && ea instanceof CsvError && eb instanceof CsvError) || (!ea && !eb && JSON.stringify(a) === JSON.stringify(b));
  if (!ok) { mismatches++; console.log("MISMATCH", JSON.stringify(s), "impl:", ea ? ea.constructor.name + ": " + ea.message : JSON.stringify(a), "ref:", eb ? eb.constructor.name : JSON.stringify(b)); }
}
console.log("fuzz done, mismatches:", mismatches);
'

